#include <algorithm>
#include <cstddef>
#include <functional>
#include <iostream>
#include <string>
#include <vector>

void printInts(const std::vector<int>& values) {
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i > 0) {
            std::cout << ' ';
        }
        std::cout << values[i];
    }
    std::cout << '\n';
}

void printWords(const std::vector<std::string>& words) {
    for (std::size_t i = 0; i < words.size(); ++i) {
        if (i > 0) {
            std::cout << ' ';
        }
        std::cout << words[i];
    }
    std::cout << '\n';
}

int main() {
    std::vector<int> nums = {5, 1, 4, 2};
    std::sort(nums.begin(), nums.end(), std::greater<int>());
    printInts(nums);

    std::vector<std::string> fruits = {"pear", "fig", "apple", "kiwi"};
    auto byLength = [](const std::string& a, const std::string& b) {
        if (a.size() != b.size()) {
            return a.size() < b.size();
        }
        return a < b;
    };
    std::sort(fruits.begin(), fruits.end(), byLength);
    printWords(fruits);

    std::vector<std::string> basket = {"pear", "fig", "plum", "kiwi", "apple"};
    std::stable_sort(basket.begin(), basket.end(),
                     [](const std::string& a, const std::string& b) {
                         return a.size() < b.size();
                     });
    printWords(basket);
    return 0;
}

