#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    const std::vector<int> ages = {12, 25, 17, 40, 15};
    const int adultAge = 18;

    const int adults = std::count_if(ages.begin(), ages.end(),
                                     [adultAge](int age) { return age >= adultAge; });
    std::cout << adults << '\n';

    auto isTeen = [](int age) { return age >= 13 && age <= 19; };
    auto it = std::find_if(ages.begin(), ages.end(), isTeen);
    if (it != ages.end()) {
        std::cout << *it << '\n';
    }

    std::cout << std::boolalpha;
    std::cout << std::any_of(ages.begin(), ages.end(), [](int age) { return age > 90; }) << ' '
              << std::all_of(ages.begin(), ages.end(), [](int age) { return age > 0; }) << ' '
              << std::none_of(ages.begin(), ages.end(), [](int age) { return age < 0; }) << '\n';
    return 0;
}

